mapper.select:
${pagingTop}
SELECT
	homepage_id, popup_zone_idx, popup_zone_name, print_seq, use_yn,
	add_id, add_date, TO_CHAR(start_date, 'yyyy-MM-dd') AS start_date, TO_CHAR(end_date, 'yyyy-MM-dd') AS end_date, org_file_name,
	server_file_name, file_extension, file_size, link_url, link_target, alt_text, school_use_yn
FROM
	CMS_POPUP_ZONE
WHERE
	homepage_id = #{homepage_id}

	AND	${search_type} LIKE '%'||#{search_text}||'%'


	AND	link_target = #{link_target}


	AND	use_yn = #{use_yn}


	AND	school_use_yn = #{school_use_yn}

ORDER BY
	print_seq ASC, add_date DESC
${pagingBottom}

SELECT
	COUNT(*)
FROM
	CMS_POPUP_ZONE
WHERE
	homepage_id = #{homepage_id}

	AND	${search_type} LIKE '%'||#{search_text}||'%'


	AND	link_target = #{link_target}


	AND	use_yn = #{use_yn}


	AND	school_use_yn = #{school_use_yn}

